import warnings
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")


def compute_total(items: list[dict], tax_rate: str = "0") -> Decimal:
    """Sum quantity * unit_price over items, then add tax, rounded half-up to cents."""
    subtotal = sum(
        (Decimal(str(i["qty"])) * Decimal(str(i["unit_price"])) for i in items), Decimal("0")
    )
    return (subtotal * (1 + Decimal(tax_rate))).quantize(CENT, rounding=ROUND_HALF_UP)


def calc_total(items: list[dict], tax_rate: str = "0") -> Decimal:
    """Deprecated alias for :func:`compute_total`."""
    warnings.warn(
        "billing.totals.calc_total is deprecated; use billing.totals.compute_total instead.",
        DeprecationWarning,
        stacklevel=2,
    )
    return compute_total(items, tax_rate)
", "path": "/app/billing/totals.py"}

{"content": "import warnings
from decimal import Decimal
import unittest

from billing.totals import calc_total, compute_total

ITEMS = [
    {"qty": 2, "unit_price": "3.50"},
    {"qty": 1, "unit_price": "10.49"},
]


class ComputeTotalTests(unittest.TestCase):
    def test_basic_total(self):
        self.assertEqual(compute_total(ITEMS), Decimal("17.49"))

    def test_with_tax(self):
        self.assertEqual(compute_total(ITEMS, "0.2"), Decimal("20.99"))


class DeprecatedAliasTests(unittest.TestCase):
    def test_calc_total_warns_and_matches(self):
        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter("always")
            result = calc_total(ITEMS, "0.2")
        self.assertEqual(result, Decimal("20.99"))
        self.assertEqual(len(caught), 1)
        self.assertTrue(issubclass(caught[0].category, DeprecationWarning))


if __name__ == "__main__":
    unittest.main()
