  BOOK        : id X(4) + title X(20) + owner X(4)            = 28 bytes
  TRANSACTION : book X(4) + amount 9(10) + seller X(4) + buyer X(4) = 22 bytes
  INPUT       : buyer X(4) + seller X(4) + book X(4) + amount 9(10) = 22 bytes
"""
from pathlib import Path

APP = Path(__file__).resolve().parent

ACC_REC = 34
BOOK_REC = 28
TRANS_REC = 22
INPUT_REC = 22


def read_records(path: Path, size: int) -> list[bytes]:
    """Read a sequential COBOL file as fixed-size records.

    A short trailing record is padded with spaces, as GnuCOBOL does.
    """
    data = path.read_bytes()
    recs = [data[i:i + size] for i in range(0, len(data), size)]
    if recs:
        recs[-1] = recs[-1].ljust(size, b" ")
    return recs


def write_records(path: Path, recs: list[bytes]) -> None:
    path.write_bytes(b"".join(recs))


def fld(rec: bytes, start: int, length: int) -> str:
    """Alphanumeric field, space-padded on the right (PIC X)."""
    return rec[start:start + length].decode("latin-1")


def num(rec: bytes, start: int, length: int) -> int:
    """Unsigned display numeric field (PIC 9); blanks/non-digits read as 0,
    matching GnuCOBOL's lenient treatment of short/padded records."""
    text = rec[start:start + length].decode("latin-1")
    digits = "".join(ch if ch.isdigit() else "0" for ch in text)
    return int(digits)


def x(value: str, length: int) -> str:
    return value[:length].ljust(length)


def z(value: int, length: int) -> str:
    value = abs(value) % (10 ** length)  # unsigned display: sign dropped, mod 10^len
    return str(value).rjust(length, "0")


def make_account(acc_id: str, name: str, balance: int) -> bytes:
    return (x(acc_id, 4) + x(name, 20) + z(balance, 10)).encode("latin-1")


def make_book(book_id: str, title: str, owner: str) -> bytes:
    return (x(book_id, 4) + x(title, 20) + x(owner, 4)).encode("latin-1")


def make_trans(book: str, amount: int, seller: str, buyer: str) -> bytes:
    return (x(book, 4) + z(amount, 10) + x(seller, 4) + x(buyer, 4)).encode("latin-1")


def main() -> None:
    buyer_id = seller_id = book_id = ""
    amount = 0  # in cents (WS-AMOUNT is PIC 9(10)V99)

    # MAIN-PARA: read the single input record.
    input_recs = read_records(APP / "src" / "INPUT.DAT", INPUT_REC)
    if not input_recs:
        print("Error: Input file is empty")
        return
    rec = input_recs[0]
    buyer_id = fld(rec, 0, 4)
    seller_id = fld(rec, 4, 4)
    book_id = fld(rec, 8, 4)
    amount = num(rec, 12, 10) * 100  # MOVE PIC 9(10) -> PIC 9(10)V99

    # VALIDATE-USERS-AND-BOOK
    buyer_found = seller_found = book_found = valid_owner = False
    for arec in read_records(APP / "data" / "ACCOUNTS.DAT", ACC_REC):
        acc_id = fld(arec, 0, 4)
        if acc_id == buyer_id:
            buyer_found = True
        if acc_id == seller_id:
            seller_found = True
    for brec in read_records(APP / "data" / "BOOKS.DAT", BOOK_REC):
        if fld(brec, 0, 4) == book_id:
            book_found = True
            if fld(brec, 24, 4) == seller_id:
                valid_owner = True
    print(" ")

    if not (buyer_found and seller_found and book_found and valid_owner):
        print("Transaction failed due to validation errors")
        return

    # PROCESS-TRANSACTION: update balances in place.
    acc_recs = read_records(APP / "data" / "ACCOUNTS.DAT", ACC_REC)
    out = []
    for arec in acc_recs:
        acc_id = fld(arec, 0, 4)
        balance = num(arec, 24, 10)
        if acc_id == buyer_id:
            balance -= amount
        if acc_id == seller_id:
            balance += amount
        if acc_id in (buyer_id, seller_id):
            arec = make_account(acc_id, fld(arec, 4, 20), balance // 100)
        out.append(arec)
    write_records(APP / "data" / "ACCOUNTS.DAT", out)

    # Transfer book ownership in place.
    book_recs = read_records(APP / "data" / "BOOKS.DAT", BOOK_REC)
    out = []
    for brec in book_recs:
        if fld(brec, 0, 4) == book_id:
            brec = make_book(book_id, fld(brec, 4, 20), buyer_id)
        out.append(brec)
    write_records(APP / "data" / "BOOKS.DAT", out)

    # OPEN EXTEND TRANSACTIONS-FILE: append one record (no terminator).
    with open(APP / "data" / "TRANSACTIONS.DAT", "ab") as f:
        f.write(make_trans(book_id, amount // 100, seller_id, buyer_id))

    print("Transaction completed successfully")


if __name__ == "__main__":
    main()
