  src/INPUT.DAT    : 28 bytes/record = buyer X(4) + seller X(4) + book X(4) + amount 9(10)
"""

import sys

DATA = "data"
ACC_LEN, BOOK_LEN, TRANS_LEN, INPUT_LEN = 34, 28, 28, 28


def read_records(path, reclen):
    """Return list of fixed-length records (space padded), like GnuCOBOL."""
    with open(path, "rb") as f:
        raw = f.read()
    recs = []
    for i in range(0, len(raw), reclen):
        recs.append(raw[i:i + reclen].decode("latin-1").ljust(reclen))
    return recs


def write_records(path, recs):
    with open(path, "wb") as f:
        f.write("".join(recs).encode("latin-1"))


def num(field):
    """PIC 9(n) display field -> integer (spaces read as zeros)."""
    digits = "".join(ch if ch.isdigit() else "0" for ch in field)
    return int(digits)


def fmt(value, width):
    """Store like an unsigned PIC 9(n): magnitude modulo 10**n."""
    return str(abs(value) % (10 ** width)).rjust(width, "0")


def main():
    # ---- read the (single) input transaction ----
    try:
        recs = read_records("src/INPUT.DAT", INPUT_LEN)
    except FileNotFoundError:
        print("Error: Input file is empty")
        sys.exit(0)
    if not recs:
        print("Error: Input file is empty")
        sys.exit(0)
    inp = recs[0]
    buyer, seller, book_id = inp[0:4], inp[4:8], inp[8:12]
    amount = num(inp[12:22])          # PIC 9(10) -> WS-AMOUNT 9(10)V99

    # ---- VALIDATE-USERS-AND-BOOK ----
    buyer_found = seller_found = book_found = valid_owner = False
    for acc in read_records(f"{DATA}/ACCOUNTS.DAT", ACC_LEN):
        if acc[0:4] == buyer:
            buyer_found = True
        if acc[0:4] == seller:
            seller_found = True
    for bk in read_records(f"{DATA}/BOOKS.DAT", BOOK_LEN):
        if bk[0:4] == book_id:
            book_found = True
            if bk[24:28] == seller:
                valid_owner = True
    print(" ")

    if not (buyer_found and seller_found and book_found and valid_owner):
        print("Transaction failed due to validation errors")
        sys.exit(0)

    # ---- PROCESS-TRANSACTION ----
    accounts = read_records(f"{DATA}/ACCOUNTS.DAT", ACC_LEN)
    for i, acc in enumerate(accounts):
        if acc[0:4] == buyer:
            bal = num(acc[24:34]) - amount
            accounts[i] = acc[0:24] + fmt(bal, 10)
        if acc[0:4] == seller:
            bal = num(acc[24:34]) + amount
            accounts[i] = acc[0:24] + fmt(bal, 10)
    write_records(f"{DATA}/ACCOUNTS.DAT", accounts)

    books = read_records(f"{DATA}/BOOKS.DAT", BOOK_LEN)
    for i, bk in enumerate(books):
        if bk[0:4] == book_id:
            books[i] = bk[0:24] + buyer
    write_records(f"{DATA}/BOOKS.DAT", books)

    trans = read_records(f"{DATA}/TRANSACTIONS.DAT", TRANS_LEN)
    trans.append(book_id + fmt(amount, 10) + seller + buyer)
    write_records(f"{DATA}/TRANSACTIONS.DAT", trans)

    print("Transaction completed successfully")


if __name__ == "__main__":
    main()
